def get_maxgold(gold, m, n):
    """Return the maximum gold collectable through the mine.

    The miner starts in any cell of the first column and, from a cell,
    may move to the cell on the right, right-up, or right-down in the
    next column. ``m`` is the number of rows and ``n`` the number of
    columns of ``gold``.
    """
    if not gold or m <= 0 or n <= 0:
        return 0

    # dp[row] is the maximum gold collectable starting from the
    # current column at that row; initialise it with the last column.
    dp = [gold[row][n - 1] for row in range(m)]

    for col in range(n - 2, -1, -1):
        new_dp = [0] * m
        for row in range(m):
            best_next = dp[row]
            if row > 0:
                best_next = max(best_next, dp[row - 1])
            if row < m - 1:
                best_next = max(best_next, dp[row + 1])
            new_dp[row] = gold[row][col] + best_next
        dp = new_dp

    return max(dp)
